    work=Path(folder)
    for name,content in sources.items():
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
    names=['FingerprintStyles','FingerprintAnimations','ClockEnabledPolicy','PreviewPolicy','xposed/SensorAnimationBackend','xposed/SensorFingerprintBackend']
    files=[str(p) for p in work.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy'/(n+'.java')) for n in names]
    subprocess.run(['java','com.sun.tools.javac.Main','-d',str(work/'classes'),*files],check=True)
    subprocess.run(['java','-cp',str(work/'classes'),'com.elitedarkkaiser.nubialy.xposed.AnimationTest'],check=True)
